from 写入第二遍 import add
add('06_004',3,'16:9，贴地低机位高跟鞋特写，黑色鞋尖从画面中央偏左压向右下石面，后跟与鞋底同框；固定机位，人物膝部以上在画外。','黑色鞋尖先轻触平台，细后跟紧接着落稳，脚踝把重心压到前脚；鞋边两粒石屑跳起又落下。来者平淡反问春子是谁，鞋面随着站稳出现一小条移动的亮反光。','灰绿石铺地面斜贯画幅下侧，鞋外上方是一小块浅蓝灰天空。','正上方冷白漫射在黑鞋上形成窄冷亮条，石面灰绿且阴影短。','鞋尖轻点接鞋跟一声清脆哒响，石屑细响。',ja=['…春子？それ、誰？'],tone='董白停一下重复陌生名字，后半句直白反问。',kind='mixed',phase='contact',node={'董白.位置':'在青身侧的平台上立足，身份尚待全身揭晓'},meaning='先见高跟鞋落地，董白从画外纠正青的误认。',characters=['董白'])
add('07_001',7,'16:9，董白完整立姿全景居画面中央，双马尾占左右空隙；镜头从鞋跟沿身体上摇再后移一小步，落幅头、双手、裙摆与立足点全在横幅内，青暂在画外左侧。','董白站稳后把下巴抬起，右手松松托起一绺马尾，手腕翻开，黑色发尾先滑过手指再慢慢落回；她圆睁双眼、嘴角上扬，先让青让开，随后把视线越过青投向武士。另一只手自然垂在身侧，身体稍向前压半分，占住接战的位置。','平台灰绿石铺地面占下幅，远处蓝灰云天大幅铺开，米灰烟尘沿低处漂过。','云天冷白光在黑发与亮黑裙面留下宽软反光，脸部由石面弱补光照亮。','马尾划过手指的轻擦，鞋底在石面上微转，平台风声。',ja=['誰だろうといいわ。今すぐそこをどきなさい。','ああいう魔物を倒すのは、魔族斬鉄団の仕事よ。'],tone='第一句轻慢且直接下令，第二句以团的身份抬高自己，语尾笃定。',kind='mixed',phase='state',node={'董白.位置':'青身侧，正面向战场','青.认识':'已看清董白全貌'},meaning='董白先露鞋再完整揭晓，托发、自信圆眼与宣布接管保留。',characters=['董白'],card={'opening':'董白自认接战资格高于青。','beats':['立稳抬下巴，托发下令','马尾从手中滑回，视线越向武士'],'coupling':'托发与命令的从容同步，身体占住接战位置。','landing':'自信接管，等青退让。'})
add('07_002',4.5,'16:9，青三分侧头肩近景居画面中央偏左，耳尖与马尾根在左上；略高于肩的机位固定，右侧留给董白的画外方向。','青看清董白，原先向前倾的身体停住，眉毛抬开，眼睛仍圆圆地睁着；她头偏了一点，先说“你是”，目光在董白脸的画外高度停住。想起那一耳光，她的嘴从小圆口变成迟疑的半张，下颌微收，头上翘起的一缕头发晚一拍摆回。','青发隙之后是蓝灰云天，浅灰云层集中在画面右侧，低处烟尘淡薄。','上方冷白漫射保持，耳缘与脸侧明暗柔软。','青短促呼气，发梢与衣领轻碰，风声。',ja=['あなたは…姉さんに平手打ちした、あの…'],tone='先迟疑辨认，再带记起旧事的警觉，停在未完整叫出的称呼上。',kind='mixed',phase='state',meaning='青认出扇过姐姐的人，圆眼迟疑与头部小偏转保留。',characters=['青'],card={'opening':'支援希望变成对熟悉面孔的意外。','beats':['倾身停、头微偏','辨认后收下巴，话停在半句'],'coupling':'迟疑顺着识别过程展开，旧事让姿态逐渐收回。','landing':'青认出对方，但还未确定能否信任。'})
